(function ($) {
  $.fn.highlightNotice = function (options) {
    const settings = $.extend({ className: "is-highlighted" }, options);
    return this.each(function () { $(this).addClass(settings.className); });
  };
})(jQuery);
$(".notice").highlightNotice();

